    'pens': [{'index': 1, 'color': {'red': 1.0, 'green': 0.0, 'blue': 0.0}, 'width': 0.5}],
    'target': 'model'
}))

aclib.PrintJson (aclib.RunTapirCommand ('ModifyPens', {
    'pens': [{'index': 1, 'color': oldPen['color'], 'width': oldPen['width']}],
    'target': 'model'
}))

