"""Adds the first load case of the project with a factor of 1.5 to a new load combination using AddLoadCasesToLoadCombination.

Needs at least one load case. Reads the combination back and deletes it at the end.
"""
import aclib

loadCases = [c for c in aclib.RunTapirCommand ('GetAnalyticalLoadCases', {})['loadCases'] if 'error' not in c]
if not loadCases:
    raise SystemExit ('No load case in the project.')
loadCombinationId = aclib.RunTapirCommand ('CreateAnalyticalLoadCombinations', {
    'loadCombinations': [{'name': 'Tapir ULS', 'category': 'ULS'}]
})['loadCombinationIds'][0]['loadCombinationId']

aclib.PrintJson (aclib.RunTapirCommand ('AddLoadCasesToLoadCombination', {
    'loadCombinationId': loadCombinationId,
    'loadFactors': [{'loadCaseId': loadCases[0]['loadCaseId'], 'factor': 1.5, 'multiplier': 1.0}]
}))

aclib.RunTapirCommand ('GetAnalyticalLoadCombinations', {})
aclib.RunTapirCommand ('DeleteAnalyticalLoadCombinations', {'loadCombinationIds': [{'loadCombinationId': loadCombinationId}]})

"""Prints the releases of the first curve members of the Structural Analytical Model with GetAnalyticalReleases.

Needs at least one curve member. Requires Archicad 27 or later (the command itself works from Archicad 26).
"""
import aclib

curveMembers = aclib.RunTapirCommand ('GetAnalyticalMembers', {})['curveMembers']
if not curveMembers:
    raise SystemExit ('No analytical curve member in the current view.')

aclib.PrintJson (aclib.RunTapirCommand ('GetAnalyticalReleases', {
    'elements': curveMembers[:3]
}))

"""Adds a hinge (free rotation around the local y axis) at the end of the first curve member with SetAnalyticalReleases.

Needs at least one curve member. Reads the release back and restores the old one.
Requires Archicad 27 or later (the command itself works from Archicad 26).
"""
import aclib

curveMembers = aclib.RunTapirCommand ('GetAnalyticalMembers', {})['curveMembers']
if not curveMembers:
    raise SystemExit ('No analytical curve member in the current view.')
memberId = curveMembers[0]['elementId']
oldRelease = aclib.RunTapirCommand ('GetAnalyticalReleases', {'elements': [{'elementId': memberId}]})['releases'][0]['release']

hinge = {
    'ux': 'Rigid', 'uy': 'Rigid', 'uz': 'Rigid', 'fix': 'Rigid', 'fiy': 'Free', 'fiz': 'Rigid',
    'amPartRef': {'elemGuid': memberId, 'partRefType': 'EndVertex'}
}
aclib.PrintJson (aclib.RunTapirCommand ('SetAnalyticalReleases', {
    'releases': [{
        'elementId': memberId,
        'release': {'guid': oldRelease['guid'], 'releaseDescriptions': oldRelease['releaseDescriptions'] + [hinge]}
    }]
}))
aclib.RunTapirCommand ('GetAnalyticalReleases', {'elements': [{'elementId': memberId}]})

aclib.PrintJson (aclib.RunTapirCommand ('SetAnalyticalReleases', {
    'releases': [{'elementId': memberId, 'release': oldRelease}]
}))

