Requires Archicad 27 or later (the command itself works from Archicad 26).
"""
import aclib

curveMembers = aclib.RunTapirCommand ('GetAnalyticalMembers', {})['curveMembers']
if len (curveMembers) < 2:
    raise SystemExit ('Fewer than two analytical curve members in the current view.')
links = aclib.RunTapirCommand ('CreateAnalyticalLinks', {
    'links': [{
        'linkSettings': {
            'geometry': 'Link1D',
            'type': 'Rigid',
            'rigidSettings': {'startConnectionType': 'RigidConnection', 'endConnectionType': 'RigidConnection'},
            'springSettings': {
                'direction': 'Global',
                'translation': {'kxType': 'Rigid', 'kyType': 'Rigid', 'kzType': 'Rigid'},
                'rotation': {'kxxType': 'Rigid', 'kyyType': 'Rigid', 'kzzType': 'Rigid'}
            }
        },
        'startElementPartRef': {'elemGuid': curveMembers[0]['elementId'], 'partRefType': 'EndVertex'},
        'endElementPartRef': {'elemGuid': curveMembers[1]['elementId'], 'partRefType': 'Edge'}
    }]
})['elements']

aclib.PrintJson (aclib.RunTapirCommand ('ConvertAnalyticalLinksToNonShortest', {
    'elements': links
}))

"""Puts a 10 kN point load on the start of the first curve member and prints it with GetAnalyticalLoads.

Needs at least one analytical curve member and one load case. Deletes the load at the end.
Requires Archicad 27 or later (the command itself works from Archicad 26).
"""
import aclib

curveMembers = aclib.RunTapirCommand ('GetAnalyticalMembers', {})['curveMembers']
loadCases = [c for c in aclib.RunTapirCommand ('GetAnalyticalLoadCases', {})['loadCases'] if 'error' not in c]
if not curveMembers or not loadCases:
    raise SystemExit ('No analytical curve member in the current view or no load case in the project.')
loads = aclib.RunTapirCommand ('CreateAnalyticalLoads', {
    'loads': [{
        'pointLoad': {
            'loadSettings': {
                'loadCaseId': loadCases[0]['loadCaseId'],
                'loadForceType': 'Force',
                'coordinateSystemType': 'Global',
                'xValue': 0.0, 'yValue': 0.0, 'zValue': -10000.0
            },
            'loadedMemberPartRef': {'elemGuid': curveMembers[0]['elementId'], 'partRefType': 'BegVertex'}
        }
    }]
})['elements']

aclib.PrintJson (aclib.RunTapirCommand ('GetAnalyticalLoads', {
    'elements': loads
}))

aclib.RunTapirCommand ('DeleteElements', {'elements': loads})

"""Puts a 10 kN point load and a 5 kN/m line load on the first curve member with CreateAnalyticalLoads.

Needs at least one analytical curve member and one load case; the loads go into the first load case. Forces are in
newtons, downward along the global z axis. Requires Archicad 27 or later (the command itself works from Archicad 26).
"""
import aclib

curveMembers = aclib.RunTapirCommand ('GetAnalyticalMembers', {})['curveMembers']
loadCases = [c for c in aclib.RunTapirCommand ('GetAnalyticalLoadCases', {})['loadCases'] if 'error' not in c]
if not curveMembers or not loadCases:
    raise SystemExit ('No analytical curve member in the current view or no load case in the project.')
memberId = curveMembers[0]['elementId']
loadCaseId = loadCases[0]['loadCaseId']
curve = aclib.RunTapirCommand ('GetAnalyticalMemberDetails', {
    'elements': [{'elementId': memberId}]
})['analyticalMembers'][0]['curveMember']['curve']

aclib.PrintJson (aclib.RunTapirCommand ('CreateAnalyticalLoads', {
    'loads': [
        {
            'pointLoad': {
                'loadSettings': {
                    'loadCaseId': loadCaseId,
                    'loadForceType': 'Force',
                    'coordinateSystemType': 'Global',
                    'xValue': 0.0, 'yValue': 0.0, 'zValue': -10000.0
                },
                'loadedMemberPartRef': {'elemGuid': memberId, 'partRefType': 'BegVertex'}
            }
        },
        {
            'edgeLoad': {
                'loadSettings': {
                    'loadCaseId': loadCaseId,
                    'loadForceType': 'Force',
                    'loadDistributionType': 'Uniform',
                    'coordinateSystemType': 'Global',
                    'startValue': {'x': 0.0, 'y': 0.0, 'z': -5000.0},
                    'endValue': {'x': 0.0, 'y': 0.0, 'z': -5000.0}
                },
                'loadedMemberPartRef': {'elemGuid': memberId, 'partRefType': 'Edge'}
            },
            'customData': {'curve': [curve]}
        }
    ]
}))

"""Subtracts a slab from a wall with CreateSolidElementLinks and reads the link back.

The wall and the slab are created by the script and deleted at the end.
"""
import aclib

# A wall and a slab cutting through it, created by this script and deleted at the end.
wall = aclib.RunTapirCommand ('CreateWalls', {
    'wallsData': [{'begCoordinate': {'x': 100.0, 'y': 100.0}, 'endCoordinate': {'x': 106.0, 'y': 100.0}, 'height': 3.0, 'floorIndex': 0}]
})['elements'][0]
slab = aclib.RunTapirCommand ('CreateSlabs', {
    'slabsData': [{
        'level': 1.5,
        'thickness': 0.3,
        'polygonCoordinates': [{'x': 102.0, 'y': 99.0}, {'x': 104.0, 'y': 99.0}, {'x': 104.0, 'y': 101.0}, {'x': 102.0, 'y': 101.0}]
    }]
})['elements'][0]

aclib.PrintJson (aclib.RunTapirCommand ('CreateSolidElementLinks', {
    'solidLinks': [{
        'targetId': wall['elementId'],
        'operatorId': slab['elementId'],
        'operation': 'Subtraction',
        'linkFlags': {'inheritOperatorAttributes': False, 'skipPolygonHoles': False}
    }]
}))

aclib.RunTapirCommand ('GetSolidElementLinks', {'elements': [wall]})

aclib.RunTapirCommand ('DeleteElements', {'elements': [wall, slab]})

"""Removes the solid element operation link between a wall and a slab with RemoveSolidElementLinks.

The wall, the slab and the link between them are created by the script first; the elements are deleted at the end.
"""
import aclib

# A wall and a slab cutting through it, created by this script and deleted at the end.
wall = aclib.RunTapirCommand ('CreateWalls', {
    'wallsData': [{'begCoordinate': {'x': 100.0, 'y': 100.0}, 'endCoordinate': {'x': 106.0, 'y': 100.0}, 'height': 3.0, 'floorIndex': 0}]
})['elements'][0]
slab = aclib.RunTapirCommand ('CreateSlabs', {
    'slabsData': [{
        'level': 1.5,
        'thickness': 0.3,
        'polygonCoordinates': [{'x': 102.0, 'y': 99.0}, {'x': 104.0, 'y': 99.0}, {'x': 104.0, 'y': 101.0}, {'x': 102.0, 'y': 101.0}]
    }]
})['elements'][0]

aclib.RunTapirCommand ('CreateSolidElementLinks', {
    'solidLinks': [{'targetId': wall['elementId'], 'operatorId': slab['elementId'], 'operation': 'Subtraction'}]
})

aclib.PrintJson (aclib.RunTapirCommand ('RemoveSolidElementLinks', {
    'solidLinks': [{'targetId': wall['elementId'], 'operatorId': slab['elementId']}]
}))

aclib.RunTapirCommand ('GetSolidElementLinks', {'elements': [wall]})

aclib.RunTapirCommand ('DeleteElements', {'elements': [wall, slab]})

"""Subtracts a small box morph from a bigger one with CreateSolidOperations.

Both morphs are created by the script and replaced by the resulting morph, which is deleted at the end.
"""
import aclib

def BoxBody (sizeX, sizeY, sizeZ):
    return {
        'bodyType': 'Solid',
        'vertices': [
            {'x': 0, 'y': 0, 'z': 0}, {'x': sizeX, 'y': 0, 'z': 0}, {'x': sizeX, 'y': sizeY, 'z': 0}, {'x': 0, 'y': sizeY, 'z': 0},
            {'x': 0, 'y': 0, 'z': sizeZ}, {'x': sizeX, 'y': 0, 'z': sizeZ}, {'x': sizeX, 'y': sizeY, 'z': sizeZ}, {'x': 0, 'y': sizeY, 'z': sizeZ}
        ],
        'polygons': [
            {'vertexIds': [0, 3, 2, 1]}, {'vertexIds': [4, 5, 6, 7]}, {'vertexIds': [0, 1, 5, 4]},
            {'vertexIds': [1, 2, 6, 5]}, {'vertexIds': [2, 3, 7, 6]}, {'vertexIds': [3, 0, 4, 7]}
        ]
    }

morphs = aclib.RunTapirCommand ('CreateMorphs', {
    'morphsData': [
        {'basePoint': {'x': 0.0, 'y': 0.0, 'z': 0.0}, 'body': BoxBody (2.0, 2.0, 1.0)},
        {'basePoint': {'x': 0.5, 'y': 0.5, 'z': 0.5}, 'body': BoxBody (1.0, 1.0, 1.0)}
    ]
})['elements']

result = aclib.RunTapirCommand ('CreateSolidOperations', {
    'operations': [{'targetId': morphs[0]['elementId'], 'operatorId': morphs[1]['elementId'], 'operation': 'Subtraction'}]
})['results'][0]
aclib.PrintJson (result)

if 'elements' in result:
    aclib.RunTapirCommand ('DeleteElements', {'elements': result['elements']})

"""Removes the merge between two slabs with UnmergeElements.

The slabs are created and merged by the script first, and deleted at the end.
"""
import aclib

# Two adjacent slabs, created by this script and deleted at the end.
slabs = aclib.RunTapirCommand ('CreateSlabs', {
    'slabsData': [
        {'level': 0.0, 'thickness': 0.3, 'polygonCoordinates': [{'x': 50.0, 'y': 50.0}, {'x': 54.0, 'y': 50.0}, {'x': 54.0, 'y': 54.0}, {'x': 50.0, 'y': 54.0}]},
        {'level': 0.0, 'thickness': 0.3, 'polygonCoordinates': [{'x': 54.0, 'y': 50.0}, {'x': 56.0, 'y': 50.0}, {'x': 56.0, 'y': 54.0}, {'x': 54.0, 'y': 54.0}]}
    ]
})['elements']

aclib.RunTapirCommand ('MergeElements', {'elements': slabs})

aclib.PrintJson (aclib.RunTapirCommand ('UnmergeElements', {
    'elementPairs': [{'elementId1': slabs[0]['elementId'], 'elementId2': slabs[1]['elementId']}]
}))

aclib.RunTapirCommand ('GetMergedElements', {'elements': slabs})

aclib.RunTapirCommand ('DeleteElements', {'elements': slabs})
